/* Estadísticas v3 · una app local-first para datos reales de baloncesto. */
'use strict';
const APP_VERSION='v3', STORE='estadisticas_shared_v2', TEAM='BUEN CONSEJO';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const num=(n,d=1)=>Number.isFinite(+n)?(+n).toLocaleString('es-ES',{minimumFractionDigits:d,maximumFractionDigits:d}):'—';
const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z0-9]+/g,' ').trim();
const minutes=s=>{if(typeof s==='number')return s;const [m,x]=String(s||'0').split(':').map(Number);return (m||0)+(x||0)/60};
const parseAI=s=>{const [a,i]=String(s||'0/0').split('/').map(Number);return {m:a||0,a:i||0}};
const clamp=(x,a=0,b=1)=>Math.max(a,Math.min(b,+x||0));
const today=()=>new Date().toISOString().slice(0,10);
const blank=()=>({version:3,team:{name:'Buen Consejo',season:'26/27'},roster:[],games:[],live:null,ops:[],lastSeq:0,settings:{api:'',token:'',role:'admin',shotSide:'auto',shotColor:'por confirmar',rivalColor:'por confirmar'}});
let state=load(), view='team', modalContext=null, fileMode='games', installPrompt=null, toastTimer;

function load(){
  try{
    const saved=JSON.parse(localStorage.getItem(STORE)||'null');
    if(saved?.version>=2)return sanitise(saved);
    for(const key of ['estadisticas_v1','estadisticas_app_v1','basket_stats_v1']){
      const old=JSON.parse(localStorage.getItem(key)||'null');
      if(old)return migrateV1(old);
    }
  }catch(e){console.warn('No se pudo leer la copia local',e)}
  return blank();
}

/* sanitise actualizado en v3 */

function migrateV1(old){
  const out=blank();
  out.roster=(old.roster||old.players||[]).filter(p=>p?.name).map(p=>({id:p.id||uid(),number:p.number||p.num||'',name:p.name}));
  out.games=(old.games||old.matches||[]).filter(g=>g?.imported||g?.source==='fbm'||g?.actaHash).map(g=>{const pair=splitLegacyShots({...g,courtMode:g.courtMode||'full'});return {
    ...g,id:g.id||uid(),source:'fbm',events:(g.events||[]).filter(e=>e.provenance==='recorded'||e.recordedAt),shotsFor:pair.for,shotsAgainst:pair.against,shots:undefined
  }});
  localStorage.setItem(STORE,JSON.stringify(out));
  return out;
}
function foldShots(points,mode='half',side='left'){
  return (points||[]).map(p=>{
    let x=+p.x,y=+p.y;
    if(mode==='full'||p.fullCourt){
      const shotSide=p.side||side||(x<=.5?'left':'right');
      if(shotSide==='right')return {x:clamp(1-y),y:clamp((1-x)*2),id:p.id||uid(),source:p.source||'migrated'};
      return {x:clamp(y),y:clamp(x*2),id:p.id||uid(),source:p.source||'migrated'};
    }
    return {x:clamp(x),y:clamp(y),id:p.id||uid(),source:p.source||'manual'};
  });
}
function splitLegacyShots(g){
  if(g.shotsFor||g.shotsAgainst)return {for:foldShots(g.shotsFor||[],'half'),against:foldShots(g.shotsAgainst||[],'half')};
  const raw=g.shots||g.shotPoints||[], ownSide=g.sourceSide||'left', mode=g.courtMode||'half', own=[],against=[];
  raw.forEach(p=>{
    const tag=String(p.team||p.kind||p.owner||'').toLowerCase();let mine=tag?!(tag.includes('rival')||tag.includes('against')||tag.includes('opponent')):true;
    if(mode==='full'&&!tag)mine=ownSide==='left'?+p.x<=.5:+p.x>=.5;
    (mine?own:against).push(p);
  });
  return {for:foldShots(own,mode,ownSide),against:foldShots(against,mode,ownSide==='left'?'right':'left')};
}

/* save actualizado en v3 */

function record(type,payload){state.ops.push({id:uid(),at:new Date().toISOString(),type,payload});save();paintSync();scheduleSync()}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2400)}
function setView(v){view=v;$$('[data-go]').forEach(b=>b.setAttribute('aria-current',b.dataset.go===v?'page':'false'));render();window.scrollTo(0,0)}


