function namePretty(n){const [last,first]=String(n).split(',');return first?first.trim().replace(/\b\w/g,c=>c.toUpperCase())+' '+last.trim().replace(/\b\w/g,c=>c.toUpperCase()):n}
function renderGames(){
  const games=state.games;
  return head('games-page','04 · Actas y mapas','Partidos','Cada tarjeta reúne el acta, lo apuntado en Directo y el mapa de nuestras canastas.',`<button class="btn" data-action="import-games">Importar acta</button><button class="btn primary" data-action="open-shot">Añadir mapa</button>`)+(!games.length?`<div class="card empty"><div class="empty-icon">□</div><h2>No hay partidos</h2><p>Importa el Excel descargado de Afición FBM. La fecha se propone y puedes corregirla antes de guardar.</p><button class="btn primary" data-action="import-games">Elegir Excel</button></div>`:`<div class="grid">${games.slice().reverse().map(g=>`<button class="card span-6" data-detail="game:${g.id}"><div class="card-head"><div><h2>${esc(g.opponent)}</h2><p>${g.home?'Casa':'Fuera'} · ${g.date||'Fecha pendiente'} · ${g.players?.length||0} jugadoras</p></div><span class="badge ${g.us>g.them?'win':'loss'}">${g.us>g.them?'Victoria':'Derrota'}</span></div><div class="metric-strip"><div class="metric"><small>Marcador</small><strong>${g.us}–${g.them}</strong></div><div class="metric"><small>Margen</small><strong>${g.us-g.them>0?'+':''}${g.us-g.them}</strong></div><div class="metric"><small>Directo</small><strong>${g.events?.length||'—'}</strong><em>${g.events?.length?'acciones':'sin datos'}</em></div><div class="metric"><small>Mapa</small><strong>${(g.shotsFor?.length||0)+(g.shotsAgainst?.length||0)||'—'}</strong><em>${(g.shotsFor?.length||g.shotsAgainst?.length)?'propias + rivales':'al subirlo'}</em></div></div></button>`).join('')}</div>`)+`</section>`;
}

